mapper.select:
SELECT c.*
FROM `novel_chapter` c
INNER JOIN `novel` n ON n.`id` = c.`novel_id`
WHERE c.`id` = #{id}
  AND n.`user_id` = #{userId}
  AND n.`deleted` = 0

SELECT COALESCE(MAX(c.`sort_order`), 0) + 1
FROM `novel_chapter` c
INNER JOIN `novel` n ON n.`id` = c.`novel_id`
WHERE c.`novel_id` = #{novelId}
  AND n.`user_id` = #{userId}
  AND n.`deleted` = 0
